def bresenham(a,b):
    (r0,c0),(r1,c1)=a,b
    cells=[]; dr,c0=abs(r1-r0),c0
    dr,dc=r1-r0,c1-c0
    sr=1 if dr>0 else -1; sc=1 if dc>0 else -1
    dr,dc=abs(dr),abs(dc)
    r,c=r0,c0
    if dr>=dc:
        err=dc*2-dr
        for _ in range(dr+1):
            cells.append((r,c))
            if err>0 or (err==0 and True): 
                pass
            r+=sr
            err+=2*dc
            if err>0: c+=sc; err-=2*dr
        # redo properly below
        cells=[]; r,c=r0,c0; err=dr//2
        for _ in range(dr+1):
            cells.append((r,c))
            err-=dc
            if err<0: c+=sc; err+=dr
            r+=sr
    else:
        cells=[]; r,c=r0,c0; err=dc//2
        for _ in range(dc+1):
            cells.append((r,c))
            err-=dr
            if err<0: r+=sr; err+=dc
            c+=sc
    return cells

